function colorFor(text) {
  var hash = 0;
  for (var i = 0; i < text.length; i++) {
    hash = (hash * 31 + text.charCodeAt(i)) >>> 0;
  }
  return 'hsl(' + (hash % 360) + ', 65%, 38%)';
}

function paint(rootEl) {
  var tags = rootEl.querySelectorAll('.card-tag');
  for (var i = 0; i < tags.length; i++) {
    tags[i].style.background = colorFor(tags[i].textContent || '');
    tags[i].style.color = '#ffffff';
  }
}

// 'card.render' fires once per card tile with args [card, cardEl].
ctx.api.middleware.register({
  name: 'color-tags',
  operations: ['card.render'],
  handler: async function(mw, next) {
    await next();
    var cardEl = mw.args && mw.args[1];
    if (cardEl && cardEl.querySelectorAll) paint(cardEl);
  }
});

// Color anything already on screen at enable time.
paint(document);
ctx.logger.info('Card color tags active');

teardownJs:
// Middleware is auto-unregistered; clear the inline styles we set on
// tiles that are still on screen.
var tags = document.querySelectorAll('.card-tag');
for (var i = 0; i < tags.length; i++) {
  tags[i].style.background = '';
  tags[i].style.color = '';
}
